insert into services (slug, title, short_description, long_description, icon, image, roles, sort_order) values
 ('it-staffing','IT Staffing','Developers, cloud and DevOps engineers, data and AI specialists, QA, ERP and IT project managers — on contract or permanent terms.','Software, cloud, data, security and QA professionals — screened for real skills, not just keywords.','code','https://images.unsplash.com/photo-1519389950473-47ba0277781c?auto=format&fit=crop&w=1200&q=80', array['Software Development','Cloud & DevOps','Data Engineering','Data Science','AI / ML','Cybersecurity','QA / Automation','ERP','IT Project Management'],1),
 ('non-it-staffing','Non-IT Staffing','Finance, accounting, engineering, operations, sales and support roles across industries.','Finance, engineering, operations, sales and support hiring with the same rigour we apply to technology roles.','briefcase','https://images.unsplash.com/photo-1581091226825-a6a2a5aee158?auto=format&fit=crop&w=1200&q=80', array['Accounting','Financial Analysis','Mechanical','Electrical','Procurement','Logistics','Inside Sales','HR Operations'],2),
 ('contract-staffing','Contract Staffing','Flexible, compliant workforce for project peaks, backfills and fixed-term needs.','Compliant contract workforce for peaks, backfills and fixed-term projects — on our payroll, deployed to you.','clock','https://images.unsplash.com/photo-1552664730-d307ca884978?auto=format&fit=crop&w=1200&q=80', array['Developers','QA','Site engineers','Support staff','Analysts'],3),
 ('permanent-recruitment','Permanent Recruitment','End-to-end hiring for full-time positions, from brief to offer acceptance.','Full-cycle recruitment for roles you need to get right the first time.','usercheck','https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?auto=format&fit=crop&w=1200&q=80', array['Leadership','Specialists','Managers','Individual contributors'],4),
 ('bulk-project-hiring','Bulk & Project Hiring','Volume hiring for new sites, expansions and time-bound programmes.','Volume hiring for new facilities, expansions and time-bound programmes, with structured screening at scale.','users','https://images.unsplash.com/photo-1522071820081-009f0129c71c?auto=format&fit=crop&w=1200&q=80', array['Sales teams','Plant staff','Support centres','Field engineers'],5),
 ('fresher-hiring','Fresher & Entry-Level Hiring','Screened graduates and early-career talent ready to start.','Screened graduates and early-career candidates, assessed for aptitude and attitude.','graduation','https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1200&q=80', array['Graduate engineers','Trainee analysts','Associate recruiters','Sales trainees'],6),
 ('training-upskilling','Training & Upskilling','Role-ready training for graduates and working professionals, aligned to what employers are hiring for now.','Short, practical programmes that close the gap between a candidate and a role — technical foundations, tools, communication and interview readiness — delivered before placement or as part of a hiring drive.','trend','https://images.unsplash.com/photo-1524178232363-1fb2b075b655?auto=format&fit=crop&w=1200&q=80', array['Pre-placement bootcamps','Employer-specific onboarding','Software & cloud foundations','Communication & interview skills'],7);
insert into faqs ("group", question, answer, sort_order) values
 ('Job seekers','Do job seekers pay anything to apply?','No. Amani Tech never charges candidates for registration, applications or placements.',1),
 ('Job seekers','How do I know a job is genuine?','Every job on this site is posted by Amani Tech’s recruitment team after confirming the requirement with the employer.',2),
 ('Job seekers','What happens after I apply?','You receive a confirmation email. A recruiter reviews your application and contacts you if the role is a fit. You can check your status in your dashboard.',3),
 ('Job seekers','Which resume formats do you accept?','PDF, DOC and DOCX up to 5 MB.',4),
 ('Job seekers','Can I apply to more than one job?','Yes. Register once and apply to as many relevant roles as you like.',5),
 ('Employers','How quickly can employers expect a shortlist?','For most roles, profiles are shared within a few working days of the requirement being confirmed.',6),
 ('Employers','Do you offer contract staffing?','Yes. We provide contract, permanent and project-based staffing.',7),
 ('Employers','Do you place non-IT candidates?','Yes — finance, engineering, operations, sales, support and more.',8),
 ('Employers','Which locations do you cover?','We place candidates across major Indian cities and remote roles. Tell us the location in your requirement and we will confirm coverage.',9),
 ('Partners','Who can become a staffing partner?','Specialist staffing firms, regional agencies, campus partners and independent recruiters with a strong candidate network.',10),
 ('General','How is my data used?','Your resume is only shared with employers for roles you apply to. See our Privacy Policy for details.',11),
 ('General','How do I contact Amani Tech?','Use the contact page, email hello@amanitech.in or call +91 40 0000 0000 during office hours.',12);
insert into site_content (key, payload, is_visible) values
 ('hero', '{"eyebrow":"Staffing & Recruitment · IT and Non-IT","heading":"Find work that moves your career forward.","accent":"career forward.","subheading":"Amani Tech connects skilled professionals with verified employers across IT and non-IT roles. Search open positions, apply in minutes, and let our recruitment team support you through every step.","primary_cta":"Search Jobs","secondary_cta":"Hiring? Request talent","secondary_url":"/employers","popular":["Java Developer","Data Engineer","Accountant","DevOps","Mechanical Engineer"],"image":"https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1200&q=80"}', true),
 ('trust_band', '{"heading":"Trusted by employers across industries","industries":["IT Services","Banking & Finance","Manufacturing","Healthcare","Retail & E-commerce","Education","Logistics","Telecom"],"logos":[]}', true),
 ('statistics', '{"items":[{"number":1200,"suffix":"+","label":"Candidates placed"},{"number":180,"suffix":"+","label":"Client companies"},{"number":25,"suffix":"+","label":"Job categories"},{"number":9,"suffix":"","label":"Years in staffing"}]}', true),
 ('employer_cta', '{"heading":"Looking for the right talent?","text":"Tell us about the role. Our recruiters will source, screen and shortlist candidates for you.","primary_cta":"Request Talent","secondary_cta":"Become a staffing partner"}', true),
 ('footer', '{"description":"Amani Tech helps job seekers find genuine opportunities and helps employers hire the right people — across IT and non-IT roles.","address":"4th Floor, Tech Park Tower, HITEC City, Hyderabad 500081, India","phone":"+91 40 0000 0000","email":"hello@amanitech.in","hours":"Mon–Sat, 9:30 AM – 6:30 PM IST","social":{"linkedin":"","instagram":"","x":"","youtube":""}}', true),
 ('settings', '{"site_name":"Amani Tech","seo_suffix":"| Amani Tech","seo_description":"Find genuine job opportunities or hire screened talent. Amani Tech connects candidates and employers across IT and non-IT roles in India.","employer_sla":"within one business day","notify_emails":"recruitment@amanitech.in, employers@amanitech.in"}', true);
