insert into blog_posts (slug, title, category, excerpt, tags, read_minutes, is_featured, status, published_at, cover_image, content) values
 ('resume-a-recruiter-will-read','How to write a resume that a recruiter will actually read','Career Advice','Recruiters spend under a minute on a first pass. Here is how to make that minute count — structure, keywords, and the mistakes that get resumes skipped.',array['Resume','Job search'],6,true,'PUBLISHED','2026-09-10','https://images.unsplash.com/photo-1586281380349-632531db7ed4?auto=format&fit=crop&w=1600&q=80',
insert into career_openings (slug, position, department, location, work_mode, experience, status, published_at, description, responsibilities, requirements, benefits, application_instructions) values
 ('senior-it-recruiter','Senior IT Recruiter','Recruitment','Hyderabad','Hybrid','4–7 years','PUBLISHED','2026-09-08','Own end-to-end recruitment for IT mandates — from understanding the requirement with the client to offer negotiation and joining.',array['Understand client requirements and build search strategies','Source, screen and present candidates with recruiter notes','Manage the candidate experience through interviews and offers','Mentor associate recruiters'],array['4–7 years in IT recruitment, agency experience preferred','Strong sourcing skills across portals, LinkedIn and referrals','Excellent communication and follow-through'],array['Health insurance','Performance incentives','Hybrid working','Learning budget'],'Email your resume to careers@amanitech.in with the subject line “Senior IT Recruiter”. Include a short note on the toughest role you have closed.'),
 ('account-manager-staffing','Account Manager — Staffing','Client Services','Bengaluru','Hybrid','5–9 years','PUBLISHED','2026-09-01','Grow and manage relationships with employer clients, ensuring requirements are understood, staffed on time and renewed.',array['Manage a portfolio of employer accounts','Translate requirements into clear briefs for the recruitment team','Track delivery, escalate risks and drive renewals','Identify expansion opportunities'],array['5–9 years in staffing account management or B2B client services','Understanding of contract and permanent staffing models','Commercial acumen'],array['Health insurance','Quarterly incentives','Hybrid working'],'Email your resume to careers@amanitech.in with the subject line “Account Manager — Staffing”.'),
 ('associate-recruiter-non-it','Associate Recruiter (Non-IT)','Recruitment','Hyderabad','On-site','0–2 years','PUBLISHED','2026-09-12','Start your recruitment career with structured training. You will support senior recruiters on finance, engineering and operations mandates.',array['Source candidates from portals and databases','Conduct first-level screening calls','Maintain trackers and schedule interviews'],array['0–2 years of experience; graduates welcome','Clear spoken and written English; Telugu or Hindi a plus','Curiosity about people and industries'],array['Structured onboarding','Health insurance','Clear promotion path'],'Email your resume to careers@amanitech.in with the subject line “Associate Recruiter”.'),
 ('full-stack-developer-internal','Full-Stack Developer (Internal Platform)','Technology','Remote','Remote','3–5 years','PUBLISHED','2026-08-25','Build and maintain the Amani Tech job platform and admin tools used by our recruiters every day.',array['Ship features across the Next.js frontend and Supabase backend','Maintain the PostgreSQL schema and API','Improve performance, accessibility and security'],array['3–5 years with TypeScript, React and Node','Experience with PostgreSQL and file storage','Product mindset'],array['Fully remote','Health insurance','Learning budget'],'Email your resume and a link to something you have built to careers@amanitech.in with the subject line “Full-Stack Developer”.');
insert into testimonials (name, designation, company, rating, review, status, is_featured, approved_at) values
 ('Priya Raman','Data Engineer','Placed via Amani Tech',5,'I had applied to dozens of portals with no response. Within a week of applying here, a recruiter called me, explained the role honestly, and prepared me for the interview. I joined in three weeks.','APPROVED',true,now()),
 ('Suresh Menon','Head of Engineering','SaaS Scale-up',5,'We needed two DevOps engineers before a product launch. Amani Tech sent four screened profiles in five days and both hires are still with us a year later.','APPROVED',true,now()),
 ('Anita Deshmukh','Plant HR Manager','Automotive Components Manufacturer',4,'Most agencies only understand IT. Amani Tech filled mechanical design and quality roles for us with candidates who actually matched the JD.','APPROVED',true,now()),
 ('Rahul Verma','SAP FICO Consultant','Placed via Amani Tech',5,'Clear communication at every step. I always knew where my application stood.','APPROVED',false,now()),
 ('Kavya Nair','Accountant','Manufacturing Group',5,'The team was patient with my questions and negotiated a fair offer on my behalf.','PENDING',false,null),
 ('Deepak Sharma','Talent Acquisition Lead','NBFC',4,'Responsive team and good quality shortlist for our FP&A roles.','PENDING',false,null);
